def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if len(cells) >= 4:
                rs = [y for y, x in cells]
                cs = [x for y, x in cells]
                comps.append((color, min(rs), max(rs), min(cs), max(cs), cells))

    out = [[bg] * w for _ in range(h)]
    for color, r0, r1, c0, c1, cells in comps:
        for r, c in cells:
            out[r][c] = color

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or out[r][c] != bg:
                continue
            for color, r0, r1, c0, c1, cells in comps:
                if r0 <= r <= r1 and c0 <= c <= c1:
                    out[r][c] = color
                    break
    return out
